cpp.setup:
auto* control = new fluent::status_info::SplashScreen(%PARENT%);
QPixmap emblem(112, 112);
emblem.setDevicePixelRatio(2.0);
emblem.fill(Qt::transparent);
QPainter emblemPainter(&emblem);
emblemPainter.setRenderHint(QPainter::Antialiasing);
QLinearGradient emblemGrad(0.0, 0.0, 56.0, 56.0);
emblemGrad.setColorAt(0.0, QColor(QStringLiteral("#3AA8FF")));
emblemGrad.setColorAt(1.0, QColor(QStringLiteral("#0067C0")));
emblemPainter.setPen(Qt::NoPen);
emblemPainter.setBrush(emblemGrad);
emblemPainter.drawRoundedRect(0, 0, 56, 56, 14, 14);
emblemPainter.setPen(Qt::white);
QFont emblemFont = emblemPainter.font();
emblemFont.setPixelSize(30);
emblemFont.setBold(true);
emblemPainter.setFont(emblemFont);
emblemPainter.drawText(QRect(0, 0, 56, 56), Qt::AlignCenter, QStringLiteral("F"));
emblemPainter.end();
control->setIcon(QIcon(emblem));
control->setIconSize(QSize(56, 56));
control->show();
